+import calculateRetryDelay from './core/calculate-retry-delay.js';
+import type {RetryObject} from './core/options.js';
+
+/**
+Preview the delay Got would compute for each retry context, without performing any requests or timers.
+
+Each context must set `retryOptions.noise` to `0`, so the result is deterministic.
+
+@returns One delay in milliseconds per context, in the same order. `0` means the request would not be retried.
+*/
+export const retrySchedule = (contexts: readonly RetryObject[]): number[] => {
+	for (const [index, {retryOptions}] of contexts.entries()) {
+		if (retryOptions.noise !== 0) {
+			throw new RangeError(`Expected \`retryOptions.noise\` to be 0 at index ${index}, got ${String(retryOptions.noise)}`);
+		}
+	}
+
+	return contexts.map(context => calculateRetryDelay(context));
+};
+
+export default retrySchedule;
diff --git a/test/retry-schedule.ts b/test/retry-schedule.ts
