+++ b/test/retry-schedule.ts
@@ -0,0 +1,110 @@
+import test from 'ava';
+import {
+	type Method,
+	Options,
+	RequestError,
+	retrySchedule,
+	type RetryObject,
+	type RetryOptions,
+} from '../source/index.js';
+
+const createRetryOptions = (overrides: Partial<RetryOptions> = {}): RetryOptions => ({
+	...new Options().retry as RetryOptions,
+	noise: 0,
+	...overrides,
+});
+
+const createError = ({code, statusCode, method = 'GET', name}: {code?: string; statusCode?: number; method?: Method; name?: string} = {}): RequestError => {
+	const error = new RequestError('test', {code}, new Options({method}));
+
+	if (statusCode !== undefined) {
+		Object.defineProperty(error, 'response', {value: {statusCode}});
+	}
+
+	if (name !== undefined) {
+		error.name = name;
+	}
+
+	return error;
+};
+
+const createContext = (overrides: Partial<RetryObject> = {}): RetryObject => ({
+	attemptCount: 1,
+	retryOptions: createRetryOptions(),
+	error: createError({code: 'ETIMEDOUT'}),
+	computedValue: Number.POSITIVE_INFINITY,
+	...overrides,
+});
+
+test('returns an empty array for empty input', t => {
+	t.deepEqual(retrySchedule([]), []);
+});
+
+test('returns exponential delays per context', t => {
+	const retryOptions = createRetryOptions({limit: 3});
+
+	t.deepEqual(retrySchedule([
+		createContext({attemptCount: 1, retryOptions}),
+		createContext({attemptCount: 2, retryOptions}),
+		createContext({attemptCount: 3, retryOptions}),
+	]), [1000, 2000, 4000]);
+});
+
+test('caps delay at `backoffLimit`', t => {
+	t.deepEqual(retrySchedule([
+		createContext({attemptCount: 2, retryOptions: createRetryOptions({limit: 10, backoffLimit: 1500})}),
+	]), [1500]);
+});
+
+test('returns 0 once attempt limit is exceeded', t => {
+	t.deepEqual(retrySchedule([
+		createContext({attemptCount: 2, retryOptions: createRetryOptions({limit: 2})}),
+		createContext({attemptCount: 3, retryOptions: createRetryOptions({limit: 2})}),
+	]), [2000, 0]);
+});
+
+test('returns 1 for `RetryError`', t => {
+	t.deepEqual(retrySchedule([
+		createContext({attemptCount: 100, error: createError({name: 'RetryError'})}),
+	]), [1]);
+});
+
+test('respects method, error code and status code eligibility', t => {
+	t.deepEqual(retrySchedule([
+		createContext({error: createError({code: 'ETIMEDOUT', method: 'POST'})}),
+		createContext({error: createError({code: 'EUNKNOWN'})}),
+		createContext({error: createError({statusCode: 503})}),
+		createContext({error: createError({statusCode: 404})}),
+		createContext({error: createError({statusCode: 413})}),
+	]), [0, 0, 1000, 0, 0]);
+});
+
+test('uses `retryAfter` within bounds', t => {
+	t.deepEqual(retrySchedule([
+		createContext({error: createError({statusCode: 503}), retryAfter: 3000, computedValue: 5000}),
+		createContext({error: createError({statusCode: 503}), retryAfter: 6000, computedValue: 5000}),
+		createContext({error: createError({statusCode: 413}), retryAfter: 2000, computedValue: 5000}),
+	]), [3000, 0, 2000]);
+});
+
+test('throws `RangeError` on nonzero noise', t => {
+	t.throws(() => retrySchedule([
+		createContext(),
+		createContext({retryOptions: createRetryOptions({noise: 100})}),
+	]), {
+		instanceOf: RangeError,
+		message: 'Expected `retryOptions.noise` to be 0 at index 1, got 100',
+	});
+
+	t.throws(() => retrySchedule([createContext({retryOptions: createRetryOptions({noise: -1})})]), {instanceOf: RangeError});
+});
+
+test('does not mutate the input', t => {
+	const contexts = [createContext({attemptCount: 2})];
+	const snapshot = structuredClone(contexts.map(({attemptCount, computedValue, retryAfter}) => ({attemptCount, computedValue, retryAfter})));
+
+	retrySchedule(contexts);
+
+	t.deepEqual(contexts.map(({attemptCount, computedValue, retryAfter}) => ({attemptCount, computedValue, retryAfter})), snapshot);
+	t.is(contexts[0]!.retryOptions.noise, 0);
+});
